const Item* find_item(const std::string& id) noexcept {for(const auto& x:items())if(x.code==id)return &x;return nullptr;}
const Recipe* find_recipe(const std::string& id) noexcept {for(const auto& x:recipes())if(x.code==id)return &x;return nullptr;}
const Service* find_service(const std::string& id) noexcept {for(const auto& x:services())if(x.code==id)return &x;return nullptr;}
bool is_native_workshop_recipe(const std::string& id) noexcept {
  const auto* r=find_recipe(id);return r && ((id=="native_cut_aluminum_panel" && r->native_binding=="original_quantified_line_panel") ||
    (id=="native_shape_aluminum_frame" && r->native_binding=="original_quantified_line_frame"));
}
industry::Recipe original_workshop_recipe(const std::string& id) {
  const auto* r=find_recipe(id);
  if(!r || !is_native_workshop_recipe(id) || r->inputs.size()!=1 || r->outputs.size()!=2)
    throw std::invalid_argument("INDUSTRY-01 is not an authorized original workshop recipe");
  auto trim=[](const std::string& s){if(s.rfind("bulk/",0)!=0)throw std::invalid_argument("non-bulk original work item");return s.substr(5);};
  auto mass=[](std::uint64_t x){if(x>static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max()))
    throw std::overflow_error("industry recipe quantity too large");return static_cast<std::int64_t>(x);};
  const bool panel=id=="native_cut_aluminum_panel";
  if(r->site_capability!=(panel?"cut":"shape") || r->work_ticks!=5 ||
     r->inputs[0].code!=(panel?"bulk/aluminum":"bulk/aluminum_panels") ||
     r->outputs[0].code!=(panel?"bulk/aluminum_panels":"bulk/aluminum_frames") ||
     r->outputs[1].code!="bulk/aluminum_scrap" || r->inputs[0].quantity!=20000 ||
     r->outputs[0].quantity!=19000 || r->outputs[1].quantity!=1000)
    throw std::invalid_argument("native recipe no longer matches original workshop contract");
  const std::string name=id=="native_cut_aluminum_panel"?"aluminum_panel":"aluminum_frame";
  return {name,r->site_capability,{{trim(r->inputs[0].code),mass(r->inputs[0].quantity)}},
    {trim(r->outputs[0].code),mass(r->outputs[0].quantity)},
    {trim(r->outputs[1].code),mass(r->outputs[1].quantity)}};
}
void validate_against_original_inventory(){
  const auto& original=inventory::Catalogue::standard();
  std::set<std::string> ids;
  for(const auto& x:items()){if(x.code.empty() || x.mass_g_per_unit==0 || x.cargo_mm3_per_unit==0 || !ids.insert(x.code).second)
    throw std::invalid_argument("invalid generated industry item");}
  for(const auto& recovery:recovery_recipes()){
    const auto& r=recovery.recipe;std::uint64_t total_input=0,total_output=0,recovered=0,discarded=0;
    for(const auto& in:r.inputs){const auto* x=find_item(in.code);if(!x || !in.quantity)
      throw std::invalid_argument("bad recovery input");
      if(in.quantity>std::numeric_limits<std::uint64_t>::max()/x->mass_g_per_unit)
        throw std::overflow_error("recovery input overflow");
      const auto mass=in.quantity*x->mass_g_per_unit;
      if(mass>std::numeric_limits<std::uint64_t>::max()-total_input)throw std::overflow_error("recovery input total overflow");
      total_input+=mass;}
    for(const auto& o:r.outputs){const auto* x=find_item(o.code);if(!x || !o.quantity)
      throw std::invalid_argument("bad recovery output");
      if(o.quantity>std::numeric_limits<std::uint64_t>::max()/x->mass_g_per_unit)
        throw std::overflow_error("recovery output overflow");
      const auto mass=o.quantity*x->mass_g_per_unit;
      if(mass>std::numeric_limits<std::uint64_t>::max()-total_output)throw std::overflow_error("recovery total overflow");
      total_output+=mass;
      if(o.code==recovery.recovered_item)recovered+=mass;
      else if(x->lifecycle=="waste")discarded+=mass;
    }
    if(!total_input || total_input!=total_output || !recovered || recovered>=total_input || !discarded)
      throw std::invalid_argument("recovery must conserve and lose useful yield");
  }
  for(const auto& r:recipes()){
    if(r.code.empty() || r.work_ticks==0 || r.inputs.empty() || r.outputs.empty())throw std::invalid_argument("invalid industry recipe");
    auto mass=[](const std::vector<Ingredient>& lines){std::uint64_t sum=0;std::set<std::string> seen;
      for(const auto& line:lines){const auto* x=find_item(line.code);
        if(!x || !line.quantity || !seen.insert(line.code).second ||
           line.quantity>std::numeric_limits<std::uint64_t>::max()/x->mass_g_per_unit)
          throw std::invalid_argument("invalid material or overflow");
        const auto add=line.quantity*x->mass_g_per_unit;
        if(add>std::numeric_limits<std::uint64_t>::max()-sum)throw std::overflow_error("recipe mass overflow");
        sum+=add;}return sum;};
    if(mass(r.inputs)!=mass(r.outputs))throw std::invalid_argument("industry physical mass imbalance");
  }
  ids.clear();
  if(legacy_units().size()!=28)throw std::invalid_argument("legacy inventory code count changed");
  for(const auto& x:legacy_units()){if(!ids.insert(x.code).second ||
    original.liters_per_unit(x.code)!=static_cast<std::int64_t>(x.storage_liters_per_unit) || !x.mass_g_per_unit)
    throw std::invalid_argument("legacy inventory audit diverges from original game");}
  for(const char* id:{"native_cut_aluminum_panel","native_shape_aluminum_frame"}){
    const auto recipe=original_workshop_recipe(id);
    industry::State s;s.feed.capacity_grams=1000000;
    s.finished.capacity_grams=1000000;s.scrap.capacity_grams=1000000;
    industry::QuantifiedLine line(recipe,{1,recipe.operation,true,true,true},s);
    if(line.cycle_ticks()!=5)throw std::invalid_argument("original factory cycle mismatch");
  }
}
